import sys

# Aumentar o limite de recursão se necessário, embora DSU iterativo não precise.
sys.setrecursionlimit(200000)

def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    K = int(data[2])

    parent = list(range(N + 1))

    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    hidrovias = []
    rodovias = []

    idx = 3
    for _ in range(M):
        u = int(data[idx])
        v = int(data[idx + 1])
        t = int(data[idx + 2])
        idx += 3
        if t == 1:
            hidrovias.append((u, v))
        else:
            rodovias.append((u, v))

    # Verifica ciclos nas hidrovias
    for u, v in hidrovias:
        if not union(u, v):
            print("N")
            return

    # Conta quantas rodovias podem ser adicionadas sem formar ciclos
    r_max = 0
    for u, v in rodovias:
        if union(u, v):
            r_max += 1

    m2 = len(rodovias)
    if m2 - r_max <= K:
        print("S")
    else:
        print("N")

if __name__ == '__main__':
    solve()
